For any \(n \in \mathbb{Z}\), we define 
\begin{equation} 
\Delta_n(\overline{a}) := Z_{N(g_n)}(g_n(\overline{a}); \overline{a})
\end{equation}
as the \emph{\(n\)-th Gram discriminant of \(Z(t)\)}.

\label{thm:B} For any $n \in \mathbb{Z}$ and $\overline{a}\in \mathbb{R}^{N(g_n)}$ the following first-order approximation holds 
\begin{equation}
 \Delta_n(\overline{a}) =Z(g_n;\overline{a})+ O(\abs{\overline{a}}^2). 
 \end{equation}

\label{thm:B2} For any $n \in \mathbb{Z}$ the second-order Hessian of $\Delta_n(r)$ is given by  
\begin{equation} 
H_n =2(-1)^n \left (  \frac{Z'(g_n)}{\ln \left ( \frac{g_n }{2 \pi } \right )}  \right )^2. 
\end{equation}

\label{thm:C} For any $n \in \mathbb{Z}$ the following holds
\begin{equation}
Z'(g_n) = \frac{1}{4} (-1)^n \ln^2 \left ( \frac{g_n}{2 \pi} \right ) \overline{1} \cdot \nabla g_n(0). 
\end{equation}
In particular, the second-order Hessian $H_n$ measures the magnitude of the local shift of $g_n(r)$ along the $t$-axis.

\label{conj:rep} Assume $g_n$ is a bad Gram point with good consecutive neighbours $g_{n \pm 1}$. Then the following (non-sharp) bound holds
\begin{equation} \label{eq:rep}
\abs{Z'(g_n) }>4 \abs{Z(g_n)}.
\end{equation}

For a given \( N \in \mathbb{N} \), we define \( \mathcal{Z}_N \) to be the $A$-parameter space consisting of functions of the form
\begin{equation}
\label{eq:var} 
Z_N(t; \overline{a}) = Z_0(t) + \sum_{k=1}^{N-1} \frac{a_k}{\sqrt{k+1}} \cos (\theta(t) - \ln(k+1) t),
\end{equation}
where \( \overline{a} = (a_1, \ldots, a_N) \) belongs to \( \mathbb{R}^N \).

For any \(n \in \mathbb{Z}\), we define 
\begin{equation} 
\Delta_n(\overline{a}) := Z_{N(g_n)}(g_n(\overline{a}); \overline{a})
\end{equation}
as the \emph{\(n\)-th Gram discriminant of \(Z(t)\)}.

According to Theorem \ref{thm:ESHO} the RH holds if and only if, for any \(n \in \mathbb{Z}\), there exists a path \(\gamma_n(r)\) in \(\mathcal{Z}_{N(t_n) }\) from \(\overline{a}=\overline{0}\) to \(\overline{a}=\overline{1}\), along which \(t_n\) does not collide with its adjacent zeros \(t_{n\pm 1}\). In particular, along such a curve the discriminant $\Delta_n(\gamma_n(r))$ does not change sign. 
Note that 
\begin{equation}
\Delta_n(\overline{0}) = Z_N(g_n; 0) = \cos(\theta(g_n))=cos(\pi n) = (-1)^{n}.
\end{equation} 
Hence, the fact that $\Delta_n(\gamma_n(r))$ does not change sign implies \eqref{eq:corrected} as required.

\label{thm:first-order} For any $n \in \mathbb{Z}$, the first-order approximation of the discriminant $\Delta_n(\overline{a})$ of the linear curve is given by  
\begin{equation} 
\Delta_{n}(\overline{a}) = Z(g_n ; \overline{a} ) +O(\abs{\overline{a}}^2).
\end{equation} 
In particular, the classical Gram's law is the first-order approximation of the corrected Gram's law for the linear curve.

Consider the function 
\begin{equation}
F_k(t;a):= \cos(\theta(t)) + \frac{a}{\sqrt{k+1}} \cos(\theta(t)- \ln(k+1)t)
\end{equation} 
and set 
\begin{equation} 
G_k(t;a):= \frac{\partial}{\partial t} F_k(t; a). 
\end{equation}
Denote by $g_n(a)$ the extremal point of $F_k(t;a)$ locally extending the gram point $g_n$. Then, by definition, the discriminant can be written as 
\begin{equation} 
\Delta_n( 0,...,0,a,0,...,0) = F_k(g_n(a);a). 
\end{equation}
Hence, by the chain rule, we have 
\begin{equation} 
\frac{\partial \Delta_{n}}{\partial a_k} (\overline{0})=\frac{\partial}{\partial a} F_k(g_n(a) ; a)(0)= \frac{\partial g_n}{\partial a}(0) \cdot G_k(g_n ; 0)+ \frac{\partial}{\partial a} F_k (g_n ; 0). 
\end{equation}
But since the Gram points are exactly the solutions of $G_k(g_n;0)=0$, we get  
\begin{equation} 
\frac{\partial \Delta_{n}}{\partial a_k} (\overline{0})=\frac{\partial}{\partial a} F_k (g_n ; 0)=\frac{1}{\sqrt{k+1} } \cos ( \theta (g_n) - \ln(k+1) g_n).
\end{equation}
The first-order approximation of the discriminant $\Delta_n(r)$ is given by   
\begin{multline} 
\Delta_{n}(\overline{a}) \approx \Delta_{n}(\overline{0})+ \nabla \Delta_{n}  (\overline{0})  \cdot \overline{a}= \\ = 
\Delta_{n}(\overline{0})+ \cdot \sum_{k=1}^N a_k \cdot \frac{\partial \Delta_{n}}{\partial a_k} (\overline{0})= \\ = \cos(\theta(g_n)) +\sum_{k=0}^N \frac{a_k}{\sqrt{k+1} } \cos ( \theta (g_n) - \ln(k+1) g_n) = Z(g_n ; r).
\end{multline}

\label{thm:CM} For any $n \in \mathbb{Z}$, the second-order Hessian is given by 
\begin{equation} \label{eq:Hess} 
H_n(\overline{a}) :=\overline{a}^T \text{Hess}_n(0) \cdot \overline{a} =2(-1)^n \left (  \frac{Z'(g_n ; \overline{a} )}{\ln \left ( \frac{g_n }{2 \pi } \right )}  \right )^2.
\end{equation}

\label{Lem:7.2}
	\begin{equation} 
\frac{\partial}{\partial a_k} g_n(\overline{a})=  \frac{\sin ( \theta (g_n(\overline{a})) - \ln(k+1) g_n(\overline{a}))}{2 \sqrt{k+1}  Z''(g_n(\overline{a}) ; \overline{a}) } \ln \left (\frac{g_n(\overline{a})}{2 \pi (k+1)^2} \right ).
\end{equation}
	In particular, 
	\begin{equation}
\frac{\partial}{\partial a_k} g_n(\overline{0})=  2 (-1)^{n+1} \frac{\sin ( \theta (g_n) - \ln(k+1) g_n)}{ \sqrt{k+1}  \ln^2 \left ( \frac{g_n}{2 \pi} \right ) } \ln \left (\frac{g_n}{2 \pi (k+1)^2} \right ). 
\end{equation}

Let $g_n(\overline{a}; \epsilon)$ 
be the $n$-th extremal point of 
\begin{equation}
F_{k,\epsilon}(t;\overline{a}):= Z_N (t ; \overline{a}) + \frac{\epsilon}{\sqrt{k+1}} \cos(\theta(t)- \ln(k+1)t).
\end{equation} 
for $0<\epsilon$ small enough. That is, the zero of the equation 
\begin{equation}
G_{k,\epsilon}(t;\overline{a}):= \frac{\partial}{\partial t} F_{k,\epsilon}(t; a)=0. 
\end{equation} 
Then according to Newton's method, one can take the following first iteration
\begin{equation}
\widetilde{g}_n(\overline{a};\epsilon) := g_n (\overline{a}) - \frac{G_{k,\epsilon}(g_n(\overline{a}) ; \overline{a})}{G_{k,\epsilon}'(g_n(\overline{a}) ;\overline{a})}, 
\end{equation} 
as an approximation of $g_n(\overline{a};\epsilon)$, which improves as $\epsilon$ decreases, see \cite{SM}. Note that 
\begin{equation}
G_{k,\epsilon}(t;\overline{a})=Z'_N (t ; \overline{a}) - \frac{\epsilon }{\sqrt{k+1}} \sin(\theta(t)- \ln(k+1)t)(\theta'(t)-\ln(k+1)). 
\end{equation}
Since $Z'_N (g_n (\overline{a}) ; \overline{a})=0$ and 
\begin{equation}
\theta'(t) = \left ( \frac{t}{2} \ln \left ( \frac{t}{2 \pi} \right ) - \frac{t}{2} -\frac{\pi}{8} \right) ' = \frac{1}{2} \ln \left ( \frac{t}{2 \pi} \right ),
\end{equation}
we have 
\begin{equation}
G_{k,\epsilon}(g_n(\overline{a}) ;\overline{a})= - \frac{\epsilon}{2\sqrt{k+1}} \sin(\theta(g_n (\overline{a}) )- \ln(k+1)g_n (\overline{a}) )\cdot  \ln \left ( \frac{g_n( \overline{a})}{2 \pi (k+1)^2} \right ). 
\end{equation}
For the derivative the main term is given by 
\begin{equation}
G'_{k,\epsilon}(g_n ( \overline{a}) ;\overline{a})= Z''_N(g_n(\overline{a})  ; \overline{a})+ O(\epsilon).
\end{equation} 
In particular, we have 
\begin{equation}
Z''_N(g_n;\overline{0})= -\cos(\theta(g_n)) (\theta'(g_n) )^2 =\frac{(-1)^{n+1}}{4} \ln^2 \left ( \frac{g_n}{2 \pi} \right ),
\end{equation}
as required.

\label{prop:7.2} For any $1 \leq k_1,k_2 \leq N$ the following holds: 
\begin{equation}
\frac{\partial^2 \Delta_{n}}{\partial a_{k_1} \partial a_{k_2}} (\overline{a}) =-\frac{1}{4 Z''(g_n(\overline{a}) ; \overline{a}) } \prod_{i=1}^2 
\frac{\sin(\theta(g_n(\overline{a}))- \ln(k_i+1) g_n (\overline{a})) \cdot \ln \left ( \frac{g_n (\overline{a})}{2 \pi (k_i+1)^2 } \right )}{\sqrt{k_i+1} } .
\end{equation}
In particular,
\begin{equation}
\frac{\partial^2 \Delta_{n}}{\partial a_{k_1} \partial a_{k_2}} (\overline{0}) =\frac{(-1)^n}{\ln^2 \left ( \frac{g_n }{2 \pi } \right )} \prod_{i=1}^2 
\frac{\sin(\ln(k_i+1) g_n) \cdot \ln \left ( \frac{g_n }{2 \pi (k_i+1)^2 } \right )}{\sqrt{(k_i+1)} } .
\end{equation}

Consider the function 
\begin{multline} 
F_{k_1,k_2,\epsilon_1,\epsilon_2}(t;\overline{a}):= Z_N(t ; \overline{a}) + \frac{\epsilon_1}{\sqrt{k_1+1}} \cos(\theta(t)- \ln(k_1+1)t)+ \\ +\frac{\epsilon_2}{\sqrt{k_2+1}} \cos(\theta(t)- \ln(k_2+1)t)
\end{multline} 
and set 
\begin{equation} 
G_{k_1,k_2,\epsilon_1,\epsilon_2}(t;\overline{a}):= \frac{\partial}{\partial t} F_{k_1,k_2,\epsilon_1,\epsilon_2}(t; \overline{a}). 
\end{equation} 
Denote by $g_n(\overline{a}; \epsilon_1,\epsilon_2)$ the extremal point of $F_{k_1,k_2}(t;a_1,a_2)$ locally extending the gram point $g_n(\overline{a})$. Then, by definition, the discriminant can be written as 
\begin{equation}
\Delta_n( a_1,...,a_{k_1}+\epsilon_1,...,a_{k_2}+\epsilon_2,..,a_N) = F_{k_1,k_2,\epsilon_1,\epsilon_2}(g_n(\overline{a}; \epsilon_1, \epsilon_2); \overline{a} ). 
\end{equation} 
Hence, by the chain rule, we have 
\begin{multline} 
\frac{\partial \Delta_{n}}{\partial \epsilon_1} ( a_1,...,a_{k_1}+\epsilon_1,...,a_{k_2}+\epsilon_2,..,a_N) =\frac{\partial}{\partial \epsilon_1} F_{k_1,k_2,\epsilon_1,\epsilon_2}(g_n(\overline{a}; \epsilon_1, \epsilon_2); \overline{a} )=\\= 
\frac{\partial g_n}{\partial \epsilon_1}(\overline{a}; \epsilon_1,\epsilon_2) \cdot G_{k_1,k_2,\epsilon_1,\epsilon_2}(g_n(\overline{a};\epsilon_1,\epsilon_2) ; \overline{a})+ \frac{\partial}{\partial \epsilon_1} F_{k_1,k_2,\epsilon_1,\epsilon_2} (g_n(\overline{a}; \epsilon_1,\epsilon_2) ; \overline{a})=\\=\frac{\partial}{\partial \epsilon_1} F_{k_1,k_2,\epsilon_1,\epsilon_2} (g_n(\overline{a}; \epsilon_1,\epsilon_2) ; \overline{a})=\\ 
=\frac{1}{\sqrt{k_1+1}} \cos(\theta(g_n(\overline{a};\epsilon_1,\epsilon_2))- \ln(k_1+1) g_n(\overline{a}; \epsilon_1,\epsilon_2)). 
\end{multline} 
Again, we use the fact that $g_n(\overline{a}; \epsilon_1,\epsilon_2)$ are, by definition, the solutions of 
\begin{equation}
G_{k_1,k_2,\epsilon_1,\epsilon_2}(g_n(\overline{a}; \epsilon_1,\epsilon_2);\overline{a})=0.
\end{equation} 
Thus, for the second derivative we have 
\begin{multline} 
\frac{\partial^2 \Delta_{n}}{\partial \epsilon_1 \partial \epsilon_2} ( a_1,...,a_{k_1}+\epsilon_1,...,a_{k_2}+\epsilon_2,..,a_N)   =\\ 
=\frac{\partial}{\partial \epsilon_2} \left ( \frac{1}{\sqrt{k_1+1}} \cos(\theta(g_n(\overline{a};\epsilon_1,\epsilon_2))- \ln(k_1+1) g_n(\overline{a}; \epsilon_1,\epsilon_2)) \right )= \\ 
= -\frac{1}{2\sqrt{k_1+1}} \sin(\theta(g_n(\overline{a};\epsilon_1,\epsilon_2))- \ln(k_1+1) g_n(\overline{a}; \epsilon_1,\epsilon_2)) \cdot \ln \left ( \frac{g_n(\overline{a}; \epsilon_1,\epsilon_2)}{2 \pi (k+1)^2 } \right )  \frac{\partial g_n}{\partial \epsilon_2} (\overline{a} ; \epsilon_1,\epsilon_2). 
\end{multline} 
By substituting $(\epsilon_1,\epsilon_2)=(0,0)$ and applying Lemma \ref{Lem:7.2} the result follows.

\label{thm:Grad}
For any $n \in \mathbb{Z}$ the following holds
\begin{equation} 
Z'(g_n ; \overline{a} ) = \frac{1}{4} (-1)^n \ln^2 \left ( \frac{g_n}{2 \pi} \right ) \overline{a} \cdot \nabla g_n(0), 
\end{equation}
where 
\begin{equation}
\nabla  g_{n} (\overline{0}) := \left (  \frac{\partial g_{n}}{\partial a_1} (\overline{0}) ,...,\frac{\partial g_{n}}{\partial a_N} (\overline{0}) \right )
\end{equation}
is the gradient of $g_n(\overline{a})$ at $ \overline{a}=\overline{0}$.

The following holds 
\begin{multline} 
Z'_N(t; \overline{a}) = -\sin(\theta(t))\theta'(t) -\sum_{k=1}^{N} \frac{a_k}{\sqrt{k+1} } \sin ( \theta (t) - \ln(k+1) t) (\theta'(t)-\ln(k+1)) = 
\\=  -\frac{1}{2} \sin(\theta(t))\ln \left ( \frac{t}{2 \pi} \right )  -\sum_{k=1}^{N} \frac{a_k}{2\sqrt{k+1} } \sin ( \theta (t) - \ln(k+1) t)  \ln \left ( \frac{t}{2 \pi (k+1)^2} \right ). 
\end{multline} 
Hence, 
\begin{equation}
Z'_N(g_n ; \overline{a})= \sum_{k=1}^{N} \frac{a_k}{2\sqrt{k+1} } \sin (\ln(k+1) g_n)  \ln \left ( \frac{g_n}{2 \pi (k+1)^2} \right ). 
\end{equation} 
But also, 
\begin{equation}
\frac{1}{4} \ln^2 \left ( \frac{g_n}{2 \pi} \right ) \frac{\partial}{\partial a_k} g_n(\overline{0})=   (-1)^{n} \frac{\sin ( \ln(k+1) g_n)}{ 2 \sqrt{k+1} } \ln \left (\frac{g_n}{2 \pi (k+1)^2} \right ). 
\end{equation} 
Hence, 
\begin{equation}
Z'(g_n ; \overline{a} ) = \frac{1}{4} (-1)^n \ln^2 \left ( \frac{g_n}{2 \pi} \right ) \overline{a} \cdot \nabla g_n(0).
\end{equation}

\label{Hess-grad} The following holds:  
\begin{enumerate} 
\item  The second-order Hessian $H_n ( \overline{1})$ measures the magnitude of the gradient $\nabla g_n(0)$. 
\item The direction of the shift of the $n$-th extremal point of $Z(t; \overline{a})$ with respect to $g_n$ is given by the sign of 
$(-1)^n Z'(g_n ; \overline{a})$.   
\end{enumerate}

For any $n \in \mathbb{Z}$ we refer to\footnote{
 Recall that in general $
\frac{Z'(t)}{Z(t)}=i \theta'(t) -\frac{1}{it-\frac{1}{2}}+\sum_{\rho} \frac{1}{\frac{1}{2}+it-\rho}- \frac{1}{2} \frac{\Gamma'(\frac{5}{4}+\frac{it}{2})}{\Gamma(\frac{5}{4}+\frac{it}{2})}+\frac{1}{2}\ln(\pi),$ see  3.2 of \cite{E}. }
\begin{equation}
\mu(g_n) := \left \vert \frac{Z'(g_n)}{Z(g_n)} \right \vert
\end{equation} 
as \emph{the viscosity of the Gram point $g_n$.}

\label{con:8.1} If $g_n$ is an isolated bad Gram point then 
\begin{equation} \label{eq:rep2}
\abs{Z'(g_n)}>4\abs{Z(g_n)}.
\end{equation} 
In particular, corrupt Gram points must be non-isolated.
